    private static final List<String> KEYS = List.of("turns", "model_calls", "tool_calls", "tokens", "cost", "elapsed_seconds", "concurrency", "input_bytes", "output_bytes");
    private static final ExecutorService EXECUTOR = Executors.newCachedThreadPool(task -> {
        Thread thread = new Thread(task, "omniwrap-sdk-session"); thread.setDaemon(true); return thread;
    });

    @SuppressWarnings("serial")
    public static final class SessionException extends RuntimeException {
        public final String code;
        public final boolean retryable = false;
        public SessionException(String message, Throwable cause, boolean inDoubt) {
            super(message, cause); code = inDoubt ? "agent_session_in_doubt" : "agent_session_refused";
        }
    }
    public record Usage(double tokens, double cost) {}
    public record Call(String id, String tool, Map<String, Object> arguments) {}
    public record Proposal(Usage usage, List<Call> calls, boolean completed, Object result) {
        public static Proposal calls(Usage usage, List<Call> calls) { return new Proposal(usage, calls, false, null); }
        public static Proposal done(Usage usage, Object result) { return new Proposal(usage, null, true, result); }
    }
    public record Receipt(String id, String tool, String argumentsHash, boolean mutation, Object result, String previous, String hash) {}
    public record Context(String protocol, Object input, List<Receipt> results, Map<String, Object> tools) {}
    public interface Provider {
        String identity();
        String version();
        CompletableFuture<Proposal> propose(Context context, Map<String, Double> remaining, Cancellation cancellation);
        CompletableFuture<Void> close(Cancellation cancellation);
    }
    public static final class Cancellation {
        private final AtomicBoolean cancelled = new AtomicBoolean();
        public Cancellation() {}
        public void cancel() { cancelled.set(true); }
        public boolean isCancelled() { return cancelled.get(); }
        public void check() { if (isCancelled() || Thread.currentThread().isInterrupted()) throw new CancellationException("session cancelled"); }
    }
    @FunctionalInterface public interface Approval {
        CompletableFuture<Boolean> approve(String operationId, String argumentsHash, Cancellation cancellation);
    }
